import{_ as n,a0 as r,w as o,s,ao as m,I as p,x as d,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 Linux 下使用 RAID（六）：設置 RAID 10 或 1 + 0（嵌套） | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（六）：設置 RAID 10 或 1 + 0（嵌套） | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（六）：設置 RAID 10 或 1 + 0（嵌套） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（六）：設置 RAID 10 或 1 + 0（嵌套） | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 6 - Setting Up RAID 10 or 1+0 (Nested) in Linux","title":"在 Linux 下使用 RAID（六）：設置 RAID 10 或 1 + 0（嵌套）","tag":"RAID","desc":""},"relativePath":"RAID/Part 6 - Setting Up RAID 10 or 1+0 (Nested) in Linux.md","filePath":"[post].md"}'),c={name:"RAID/Part 6 - Setting Up RAID 10 or 1+0 (Nested) in Linux.md"};function l(D,e,R,A,I,h){const t=r("Link");return o(),s("div",null,[e[13]||(e[13]=m(`<h1 id="在-linux-下使用-raid-六-設置-raid-10-或-1-0-嵌套" tabindex="-1">在 Linux 下使用 RAID（六）：設置 RAID 10 或 1 + 0（嵌套） <a class="header-anchor" href="#在-linux-下使用-raid-六-設置-raid-10-或-1-0-嵌套" aria-label="Permalink to “在 Linux 下使用 RAID（六）：設置 RAID 10 或 1 + 0（嵌套）”">​</a></h1><p>RAID 10 是組合 RAID 1 和 RAID 0 形成的。要設置 RAID 10，我們至少需要4個磁盤。在之前的文章中，我們已經看到了如何使用最少兩個磁盤設置 RAID 1 和 RAID 0。</p><p>在這裏，我們將使用最少4個磁盤組合 RAID 1 和 RAID 0 來設置 RAID 10。假設我們已經在用 RAID 10 創建的邏輯卷保存了一些數據。比如我們要保存數據 “TECMINT”，它將使用以下方法將其保存在4個磁盤中。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/raid10.jpg" alt="Create Raid 10 in Linux"></p><p><em>在 Linux 中創建 Raid 10（LCTT 譯註：此圖有誤，請參照文字説明和本系列第一篇文章）</em></p><p>RAID 10 是先做鏡像，再做條帶。因此，在 RAID 1 中，相同的數據將被寫入到兩個磁盤中，“T”將同時被寫入到第一和第二個磁盤中。接着的數據被條帶化到另外兩個磁盤，“E”將被同時寫入到第三和第四個磁盤中。它將繼續循環此過程，“C”將同時被寫入到第一和第二個磁盤，以此類推。</p><p>（LCTT 譯註：原文中此處描述混淆有誤，已經根據實際情況進行修改。）</p><p>現在你已經瞭解 RAID 10 怎樣組合 RAID 1 和 RAID 0 來工作的了。如果我們有4個20 GB 的磁盤，總共為 80 GB，但我們將只能得到40 GB 的容量，另一半的容量在構建 RAID 10 中丟失。</p><h4 id="raid-10-的優點和缺點" tabindex="-1">RAID 10 的優點和缺點 <a class="header-anchor" href="#raid-10-的優點和缺點" aria-label="Permalink to “RAID 10 的優點和缺點”">​</a></h4><ul><li>提供更好的性能。</li><li>在 RAID 10 中我們將失去一半的磁盤容量。</li><li>讀與寫的性能都很好，因為它會同時進行寫入和讀取。</li><li>它能解決資料庫的高 I/O 磁盤寫操作。</li></ul><h4 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h4><p>在 RAID 10 中，我們至少需要4個磁盤，前2個磁盤為 RAID 1，其他2個磁盤為 RAID 0，就像我之前説的，RAID 10 僅僅是組合了 RAID 0和1。如果我們需要擴展 RAID 組，最少需要添加4個磁盤。</p><p><strong>我的服務器設置</strong></p><pre><code>操作系統 :	CentOS 6.5 Final
IP 地址	 	:	192.168.0.229
主機名	 	:	rd10.tecmintlocal.com
磁盤 1 [20GB]	 	:	/dev/sdd
磁盤 2 [20GB]	 	:	/dev/sdc
磁盤 3 [20GB]	 	:	/dev/sdd
磁盤 4 [20GB]	 	:	/dev/sde
</code></pre><p>有兩種方法來設置 RAID 10，在這裏兩種方法我都會演示，但我更喜歡第一種方法，使用它來設置 RAID 10 更簡單。</p><h3 id="方法1-設置-raid-10" tabindex="-1">方法1：設置 RAID 10 <a class="header-anchor" href="#方法1-設置-raid-10" aria-label="Permalink to “方法1：設置 RAID 10”">​</a></h3><p>1、 首先，使用以下命令確認所添加的4塊磁盤沒有被使用。</p><pre><code># ls -l /dev | grep sd
</code></pre><p>2、 四個磁盤被檢測後，然後來檢查磁盤是否存在 RAID 分區。</p><pre><code># mdadm -E /dev/sd[b-e]
# mdadm --examine /dev/sdb /dev/sdc /dev/sdd /dev/sde # 或
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Verify-4-Added-Disks.png" alt="Verify 4 Added Disks"></p><p><em>驗證添加的4塊磁盤</em></p><p><strong>注意</strong>: 在上面的輸出中，如果沒有檢測到 super-block 意味着在4塊磁盤中沒有定義過 RAID。</p><h4 id="第1步-為-raid-分區" tabindex="-1">第1步：為 RAID 分區 <a class="header-anchor" href="#第1步-為-raid-分區" aria-label="Permalink to “第1步：為 RAID 分區”">​</a></h4><p>3、 現在，使用<code>fdisk</code>，命令為4個磁盤(/dev/sdb, /dev/sdc, /dev/sdd 和 /dev/sde)創建新分區。</p><pre><code># fdisk /dev/sdb
# fdisk /dev/sdc
# fdisk /dev/sdd
# fdisk /dev/sde
</code></pre><p>#####為 /dev/sdb 創建分區#####</p><p>我來告訴你如何使用 fdisk 為磁盤(/dev/sdb)進行分區，此步也適用於其他磁盤。</p><pre><code># fdisk /dev/sdb
</code></pre><p>請使用以下步驟為 /dev/sdb 創建一個新的分區。</p><ul><li>按 <code>n</code> 創建新的分區。</li><li>然後按 <code>P</code> 選擇主分區。</li><li>接下來選擇分區號為1。</li><li>只需按兩次回車鍵選擇默認值即可。</li><li>然後，按 <code>P</code> 來打印創建好的分區。</li><li>按 <code>L</code>，列出所有可用的類型。</li><li>按 <code>t</code> 去修改分區。</li><li>鍵入 <code>fd</code> 設置為 Linux 的 RAID 類型，然後按 Enter 確認。</li><li>然後再次使用<code>p</code>查看我們所做的更改。</li><li>使用<code>w</code>保存更改。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Disk-sdb-Partition.png" alt="Disk sdb Partition"></p><p><em>為磁盤 sdb 分區</em></p><p><strong>注意</strong>: 請使用上面相同的指令對其他磁盤(sdc, sdd sdd sde)進行分區。</p><p>4、 創建好4個分區後，需要使用下面的命令來檢查磁盤是否存在 raid。</p><pre><code># mdadm -E /dev/sd[b-e]
# mdadm --examine /dev/sdb /dev/sdc /dev/sdd /dev/sde # 或

# mdadm -E /dev/sd[b-e]1
# mdadm --examine /dev/sdb1 /dev/sdc1 /dev/sdd1 /dev/sde1 # 或
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-All-Disks-for-Raid.png" alt="Check All Disks for Raid"></p><p><em>檢查磁盤</em></p><p><strong>注意</strong>: 以上輸出顯示，新創建的四個分區中沒有檢測到 super-block，這意味着我們可以繼續在這些磁盤上創建 RAID 10。</p><h4 id="第2步-創建-raid-設備-md" tabindex="-1">第2步: 創建 RAID 設備 <code>md</code> <a class="header-anchor" href="#第2步-創建-raid-設備-md" aria-label="Permalink to “第2步: 創建 RAID 設備 md”">​</a></h4><p>5、 現在該創建一個<code>md</code>（即 /dev/md0）設備了，使用“mdadm” raid 管理工具。在創建設備之前，必須確保系統已經安裝了<code>mdadm</code>工具，如果沒有請使用下面的命令來安裝。</p><pre><code># yum install mdadm		[在 RedHat 系統]
# apt-get install mdadm 	[在 Debain 系統]
</code></pre><p><code>mdadm</code>工具安裝完成後，可以使用下面的命令創建一個<code>md</code> raid 設備。</p><pre><code># mdadm --create /dev/md0 --level=10 --raid-devices=4 /dev/sd[b-e]1
</code></pre><p>6、 接下來使用<code>cat</code>命令驗證新創建的 raid 設備。</p><pre><code># cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-md-raid-Device.png" alt="Create md raid Device"></p><p><em>創建 md RAID 設備</em></p><p>7、 接下來，使用下面的命令來檢查4個磁盤。下面命令的輸出會很長，因為它會顯示4個磁盤的所有信息。</p><pre><code># mdadm --examine /dev/sd[b-e]1
</code></pre><p>8、 接下來，使用以下命令來查看 RAID 陣列的詳細信息。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-Array-Details.png" alt="Check Raid Array Details"></p><p><em>查看 RAID 陣列詳細信息</em></p><p><strong>注意</strong>: 你在上面看到的結果，該 RAID 的狀態是 active 和re-syncing。</p><h4 id="第3步-創建文件系統" tabindex="-1">第3步：創建文件系統 <a class="header-anchor" href="#第3步-創建文件系統" aria-label="Permalink to “第3步：創建文件系統”">​</a></h4><p>9、 使用 ext4 作為<code>md0′的文件系統，並將它掛載到</code>/mnt/raid10\`下。在這裏，我用的是 ext4，你可以使用你想要的文件系統類型。</p><pre><code># mkfs.ext4 /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-md-Filesystem.png" alt="Create md Filesystem"></p><p><em>創建 md 文件系統</em></p><p>10、 在創建文件系統後，掛載文件系統到<code>/mnt/raid10</code>下，並使用<code>ls -l</code>命令列出掛載點下的內容。</p><pre><code># mkdir /mnt/raid10
# mount /dev/md0 /mnt/raid10/
# ls -l /mnt/raid10/
</code></pre><p>接下來，在掛載點下創建一些文件，並在文件中添加些內容，然後檢查內容。</p><pre><code># touch /mnt/raid10/raid10_files.txt
# ls -l /mnt/raid10/
# echo &quot;raid 10 setup with 4 disks&quot; &gt; /mnt/raid10/raid10_files.txt
# cat /mnt/raid10/raid10_files.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Mount-md-Device.png" alt="Mount md Device"></p><p><em>掛載 md 設備</em></p><p>11、 要想自動掛載，打開<code>/etc/fstab</code>文件並添加下面的條目，掛載點根據你環境的不同來添加。使用 wq! 保存並退出。</p><pre><code># vim /etc/fstab

/dev/md0                /mnt/raid10              ext4    defaults        0 0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/AutoMount-md-Device.png" alt="AutoMount md Device"></p><p><em>掛載 md 設備</em></p><p>12、 接下來，在重新啓動系統前使用<code>mount -a</code>來確認<code>/etc/fstab</code>文件是否有錯誤。</p><pre><code># mount -av
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Errors-in-Fstab.png" alt="Check Errors in Fstab"></p><p><em>檢查 Fstab 中的錯誤</em></p><h4 id="第四步-保存-raid-配置" tabindex="-1">第四步：保存 RAID 配置 <a class="header-anchor" href="#第四步-保存-raid-配置" aria-label="Permalink to “第四步：保存 RAID 配置”">​</a></h4><p>13、 默認情況下 RAID 沒有配置文件，所以我們需要在上述步驟完成後手動保存它。</p><pre><code># mdadm --detail --scan --verbose &gt;&gt; /etc/mdadm.conf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Save-Raid10-Configuration.png" alt="Save Raid10 Configuration"></p><p><em>保存 RAID10 的配置</em></p><p>就這樣，我們使用方法1創建完了 RAID 10，這種方法是比較容易的。現在，讓我們使用方法2來設置 RAID 10。</p><h3 id="方法2-創建-raid-10" tabindex="-1">方法2：創建 RAID 10 <a class="header-anchor" href="#方法2-創建-raid-10" aria-label="Permalink to “方法2：創建 RAID 10”">​</a></h3><p>1、 在方法2中，我們必須定義2組 RAID 1，然後我們需要使用這些創建好的 RAID 1 的集合來定義一個 RAID 0。在這裏，我們將要做的是先創建2個鏡像（RAID1），然後創建 RAID0 （條帶化）。</p><p>首先，列出所有的可用於創建 RAID 10 的磁盤。</p><pre><code># ls -l /dev | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/List-4-Devices.png" alt="List 4 Devices"></p><p><em>列出了 4 個設備</em></p><p>2、 將4個磁盤使用<code>fdisk</code>命令進行分區。對於如何分區，您可以按照上面的第1步。</p><pre><code># fdisk /dev/sdb
# fdisk /dev/sdc
# fdisk /dev/sdd
# fdisk /dev/sde
</code></pre><p>3、 在完成4個磁盤的分區後，現在檢查磁盤是否存在 RAID塊。</p><pre><code># mdadm --examine /dev/sd[b-e]
# mdadm --examine /dev/sd[b-e]1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Examine-4-Disks.png" alt="Examine 4 Disks"></p><p><em>檢查 4 個磁盤</em></p><h4 id="第1步-創建-raid-1" tabindex="-1">第1步：創建 RAID 1 <a class="header-anchor" href="#第1步-創建-raid-1" aria-label="Permalink to “第1步：創建 RAID 1”">​</a></h4><p>4、 首先，使用4塊磁盤創建2組 RAID 1，一組為<code>sdb1′和 </code>sdc1′，另一組是<code>sdd1′ 和 </code>sde1′。</p><pre><code># mdadm --create /dev/md1 --metadata=1.2 --level=1 --raid-devices=2 /dev/sd[b-c]1
# mdadm --create /dev/md2 --metadata=1.2 --level=1 --raid-devices=2 /dev/sd[d-e]1
# cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Creating-Raid-1.png" alt="Creating Raid 1"></p><p><em>創建 RAID 1</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Creating-Raid-1.png" alt="Check Details of Raid 1"></p><p><em>查看 RAID 1 的詳細信息</em></p><h4 id="第2步-創建-raid-0" tabindex="-1">第2步：創建 RAID 0 <a class="header-anchor" href="#第2步-創建-raid-0" aria-label="Permalink to “第2步：創建 RAID 0”">​</a></h4><p>5、 接下來，使用 md1 和 md2 來創建 RAID 0。</p><pre><code># mdadm --create /dev/md0 --level=0 --raid-devices=2 /dev/md1 /dev/md2
# cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Creating-Raid-0.png" alt="Creating Raid 0"></p><p><em>創建 RAID 0</em></p><h4 id="第3步-保存-raid-配置" tabindex="-1">第3步：保存 RAID 配置 <a class="header-anchor" href="#第3步-保存-raid-配置" aria-label="Permalink to “第3步：保存 RAID 配置”">​</a></h4><p>6、 我們需要將配置文件保存在<code>/etc/mdadm.conf</code>文件中，使其每次重新啓動後都能加載所有的 RAID 設備。</p><pre><code># mdadm --detail --scan --verbose &gt;&gt; /etc/mdadm.conf
</code></pre><p>在此之後，我們需要按照方法1中的第3步來創建文件系統。</p><p>就是這樣！我們採用的方法2創建完了 RAID 1+0。我們將會失去一半的磁盤空間，但相比其他 RAID ，它的性能將是非常好的。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>在這裏，我們採用兩種方法創建 RAID 10。RAID 10 具有良好的性能和冗餘性。希望這篇文章可以幫助你瞭解 RAID 10 嵌套 RAID。在後面的文章中我們會看到如何擴展現有的 RAID 陣列以及更多精彩的內容。</p><hr>`,112)),p("p",null,[e[1]||(e[1]=d("via: ",-1)),a(t,{href:"http://www.tecmint.com/create-raid-10-in-linux/"},{default:i(()=>[...e[0]||(e[0]=[d("http://www.tecmint.com/create-raid-10-in-linux/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=d("作者：",-1)),a(t,{href:"http://www.tecmint.com/author/babinlonston/"},{default:i(()=>[...e[2]||(e[2]=[d("Babin Lonston",-1)])]),_:1}),e[6]||(e[6]=d(" 譯者：",-1)),a(t,{href:"https://github.com/strugglingyouth"},{default:i(()=>[...e[3]||(e[3]=[d("strugglingyouth",-1)])]),_:1}),e[7]||(e[7]=d(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[d("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=d("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[d("LCTT",-1)])]),_:1}),e[11]||(e[11]=d(" 原創翻譯，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[d("Linux中國",-1)])]),_:1}),e[12]||(e[12]=d(" 榮譽推出",-1))])])}const g=n(c,[["render",l]]);export{w as __pageData,g as default};
